OK, I think I need to look at this from a completely different angle. Let me look at the `_zip_read_cdir` function's handling of the central directory data when `cd->offset >= buf_offset`:

```c
if (cd->offset >= buf_offset) {
    zip_uint8_t *data;
    _zip_buffer_set_offset(buffer, cd->offset - buf_offset);
    if ((data = _zip_buffer_get(buffer, cd->size)) == NULL) {
        zip_error_set(error, ZIP_ER_INCONS, 0);
        _zip_cdir_free(cd);
        return NULL;
    }
    if ((cd_buffer = _zip_buffer_new(data, cd->size)) == NULL) {
        zip_error_set(error, ZIP_ER_MEMORY, 0);
        _zip_cdir_free(cd);
        return NULL;
    }
